INSERT INTO centers (name, category, conditions_text, dosha_focus, price_tier, phone, latitude, longitude, district, address, verified_status, notes, google_rating, google_review_count, nlp_quality_score, nlp_quality_source) VALUES ('Meethirigala Nissarana Vanaya Forest Monastery', 'Spiritual/Meditation', 'Satipatthana Vipassana (Mahasi tradition), flexible 1-10+ day stays', 'Balanced', 'Budget (Donation-based)', '+94 332 253 295', 6.9974048, 80.1722628, 'Mitirigala (near Gampaha)', 'Mitirigala Nissarana Aranya Rd', 'Yes', 'Well-organized, English+Sinhala instruction, free', 4.8, 371, 4.8, 'Google Rating (fallback - insufficient review data)');
INSERT INTO centers (name, category, conditions_text, dosha_focus, price_tier, phone, latitude, longitude, district, address, verified_status, notes, google_rating, google_review_count, nlp_quality_score, nlp_quality_source) VALUES ('Nauyana Yogashrama Sri Pada Aranya Senasanaya', 'Spiritual/Meditation', 'Mountain-slope forest hermitage meditation', 'Balanced', 'Budget (Donation-based)', '+94 70 395 8035', 6.6605348, 80.5548018, 'Thotilagama', 'Kuttapitiya, Thotilagama 70070', 'Yes', 'Scenic, tranquil, less touristed', 4.5, 29, 4.5, 'Google Rating (fallback - insufficient review data)');
INSERT INTO reviews (center_id, review_text) VALUES (1, 'Went to this hospital as I live close to it and needed treatment. Very disorganized place. People are mostly kind but disorganized and no hygiene practices at all. I was asked to go to the canteen and buy a pair of gloves and the person selling food just handed me the gloves in a very unsterile manner. The treatment room bed had large patches of blood and was very unclean.');
INSERT INTO reviews (center_id, review_text) VALUES (1, 'The Ayurveda National Hospital of Sri Lanka, located in Rajagiriya, stands as the premier institution for traditional Ayurvedic medicine in the country. It is highly regarded for providing excellent, authentic, and high-quality Ayurveda treatment to patients across the island.');
INSERT INTO reviews (center_id, review_text) VALUES (1, 'good service. There is a teaching hospital. But i kindly request that they should ask patients opinion before we use them as learning materials.');
INSERT INTO reviews (center_id, review_text) VALUES (1, 'Perfect place for get Ayurwedic treatments from well experienced doctors. you can take medicines for many long lasting illnesses. its a teaching hospital also.');
INSERT INTO reviews (center_id, review_text) VALUES (2, 'I visited Ayu Lanka for a full steam treatment, and it was a wonderful experience from start to finish. The atmosphere was calm, clean, and very relaxing. A special thanks to Uthpala, who carried out my treatment with great care and professionalism.');
INSERT INTO reviews (center_id, review_text) VALUES (2, 'I had a very positive experience at Ayu Lanka Hospital. The staff were professional, caring, and made me feel comfortable throughout my treatment. The environment was clean, peaceful, and welcoming.');
INSERT INTO reviews (center_id, review_text) VALUES (2, 'Today I visited Ayu Lanka Enderamulla for a full steam treatment. My experience was really amazing. The full body massage was relaxing and professionally done. The staff were caring and courteous. The facility was clean, well maintained and peaceful.');
INSERT INTO reviews (center_id, review_text) VALUES (2, 'Excellent Services and great job team. The staff of the institution is very kind, including the chief doctor Dr. Chamila Nishadari, all the doctors are very kind and friendly in treating both physical and mental illnesses.');
INSERT INTO reviews (center_id, review_text) VALUES (3, 'Amazing experience with such a nice people! We met the owner at the restaurant and he invited us to help my boyfriend. He has problems with stomach and this clinic took care of him and us.');
INSERT INTO reviews (center_id, review_text) VALUES (3, 'Me and my girlfriend had the full body, the herbal steam bath and herbal fomentation. This was easily the best massage and experience we have had. Staff explained all treatments and let us choose from many choices.');
INSERT INTO reviews (center_id, review_text) VALUES (3, 'I had a fantastic experience here, it started with a consultation and then after I went into my treatments. The full body massage was wonderful and so relaxing. I also had a steam bath and shirodhara.');
INSERT INTO reviews (center_id, review_text) VALUES (3, 'I''ve visited this place several times for a massage, and today I had the best massage I''ve experienced so far in Sri Lanka. Bhagya was absolutely amazing.');
INSERT INTO reviews (center_id, review_text) VALUES (4, 'Had the best therapy out there at Ayu Lanka Kottawa. A mind relaxing, soothing massage with a proper consultation. The staff was even amazing and they had a warm welcome.');
INSERT INTO reviews (center_id, review_text) VALUES (4, 'HIGH Professional treatment i ever feel. Calm atmosphere, clean area, professional & helpfull therapist, you must try their treatment as once in your life.');
INSERT INTO reviews (center_id, review_text) VALUES (4, 'I was suffering with elbow pain last week. The doctors & nurses treated me well. I feel so much better. Thank you Ayu Lanka team for your kindness.');
INSERT INTO reviews (center_id, review_text) VALUES (4, 'Very qualified staff with good care');
INSERT INTO reviews (center_id, review_text) VALUES (5, 'This is a great place to get your treatment specially for people who were told to do a bypass surgery. The treatment of course is longer but results from people who have gone through Dr. S S Gunawardena have claimed results of cure beyond expectations. The luxury rooms are like a hotel room with all facilities.');
INSERT INTO reviews (center_id, review_text) VALUES (5, 'One of my best friend in UK he recommended Adhitya Ayurveda Centre, I came here to obtain some treatment for severe neck pain and stiffness along with weight loss program and diet plan. I''m really happy about the treatment methods and services I received.');
INSERT INTO reviews (center_id, review_text) VALUES (5, 'Spent here 6 days anuradhapura hospital just returned how I joined. No betterment in any condition. Joined for muscle stiffness and back pain nobody asked where the pain is just did treatment, booked for 7 days but vacated after 5th day, when I inform I want to go early they were very keen on not refunding my money.');
INSERT INTO reviews (center_id, review_text) VALUES (5, 'Dr. S.S. Gunawardena is a proven and renowned traditional/Ayurvedic doctor, well known for treating many health conditions, especially heart-related issues. This place offers both treatments and wellness packages, and they are truly worth it.');
INSERT INTO reviews (center_id, review_text) VALUES (6, 'Last Tuesday we myself and my wife have done full body massage. It was a great session we enjoyed very much with highest relaxation. Supun and Ayesha were our Therapist and they were very professional.');
INSERT INTO reviews (center_id, review_text) VALUES (6, 'I went with my Wife to get a foot massage for myself and a neck/shoulder massage for her. I have a bad case of Plantar fasciitis. Upon arriving at the Spa, we were checked in by the resident doctor who did a thorough but quick examination.');
INSERT INTO reviews (center_id, review_text) VALUES (6, 'Anoma and the staff at Siddhalepa go beyond their duty to give a great massage service. The space inside the spa was beautiful. All staff are experienced, professional and help you to feel relaxed and calm.');
INSERT INTO reviews (center_id, review_text) VALUES (6, 'I had a wonderful half-day experience at Siddhalepa Clinic. My therapist, Ayesha, was professional, attentive, and highly skilled. The half-day package is a must-try and offers excellent value for money.');
INSERT INTO reviews (center_id, review_text) VALUES (7, 'I had the opportunity to get treatment for my grandmother''s back pain at Ceylon Hospital, Yakkala. We were very satisfied with the service provided by the hospital staff. Everyone was caring, professional, and attentive to our needs.');
INSERT INTO reviews (center_id, review_text) VALUES (7, 'I am receiving treatment for sciatica at Ceylon Hospital under Dr. Rusiru. I have been attending treatment for the past 5 days. Since starting treatment with her, I have felt significant improvement.');
INSERT INTO reviews (center_id, review_text) VALUES (7, 'I had a very positive experience with Dr. Udeni Dhanushka. The doctor was professional, patient, and compassionate throughout my mother''s visit.');
INSERT INTO reviews (center_id, review_text) VALUES (7, 'Yesterday I went with my wife for her knee pain. After delaying nearly 1 hour than our appointment time we get to meet the doctor. This process was excruciatingly painful for her as she nearly cried several times.');
INSERT INTO reviews (center_id, review_text) VALUES (8, 'I recently completed a 14-day stay at this wonderful Ayurveda clinic in Sri Lanka, and I cannot recommend it highly enough. The entire medical team and staff were incredibly caring, attentive, and professional throughout my stay.');
INSERT INTO reviews (center_id, review_text) VALUES (8, 'I have just finished up an 18 day panchakarma treatment here, and I am so so happy I came. From the moment I entered the centre, I felt so taken care of and looked after. The Doctor is very attentive.');
INSERT INTO reviews (center_id, review_text) VALUES (8, 'Now it''s nearly 2 months ago since I finished my Ayurveda in Sarana Beach Hospital. Thank you so much Dr. Ravindra for you helping hands and your support. I''m so thankful that I came to your new place.');
INSERT INTO reviews (center_id, review_text) VALUES (8, 'I camped here for my scouting hike and it was a really nice place I enjoyed my short while there and give thanks to the wonderful owner and the kind and helpful staff.');
INSERT INTO reviews (center_id, review_text) VALUES (9, 'Initially, we came to Ayuthantra Wellness for my husband''s hip pain, and it was relieved within just two massage sessions. Later, after he had a fall, his foot was badly swollen and we were extremely worried.');
INSERT INTO reviews (center_id, review_text) VALUES (9, 'I visited Ayuthantra for the first time last week, and although the charges are a bit pricey, the overall experience exceeded my expectations. I highly recommend it to anyone looking for genuine care.');
INSERT INTO reviews (center_id, review_text) VALUES (9, 'I''ve been visiting Ayuthantra for the past 4-5 years, and the experience has always been consistently excellent. Doctor Udari''s knowledge and expertise are truly impressive.');
INSERT INTO reviews (center_id, review_text) VALUES (9, 'I recently went for my second treatment at Ayuthantra, and I must say the experience was truly wonderful. The treatments were carried out with great care and professionalism.');
INSERT INTO reviews (center_id, review_text) VALUES (10, 'We are very grateful for the excellent Ayurvedic treatment my mother received. The doctor was extremely kind, patient, and took time to understand her pain. We have seen a clear improvement.');
INSERT INTO reviews (center_id, review_text) VALUES (10, 'Good service... Government Hospital.. Nice and quiet place...');
INSERT INTO reviews (center_id, review_text) VALUES (10, 'A meditating place located with various kinds of views. Looks more like a resort to me than a hospital.');
INSERT INTO reviews (center_id, review_text) VALUES (10, 'No crowd at all. Get ur medicines freely');
INSERT INTO reviews (center_id, review_text) VALUES (11, 'I recently visited Adithya Ayurveda in Colombo with my mother, and we had an absolutely wonderful experience. The environment is peaceful, relaxing, and beautifully maintained. The treatments were excellent and provided a truly rejuvenating experience.');
INSERT INTO reviews (center_id, review_text) VALUES (11, 'While in Colombo, we did a 5 day treatment package with Adhitya. Upon booking the reception was responsive and informative, and the treatments we had were completely restorative.');
INSERT INTO reviews (center_id, review_text) VALUES (11, 'I''ve always known Adhitya Ayurveda Colombo for their treatments, but I didn''t expect their food to be this good. The cookies are honestly amazing.');
INSERT INTO reviews (center_id, review_text) VALUES (11, 'Had a wonderful experience at this Ayurvedic spa. The ambience is peaceful, relaxing, and beautifully maintained. All treatments are carried out under the supervision of a doctor, which gave me added confidence.');
INSERT INTO reviews (center_id, review_text) VALUES (12, 'For the past 4 years, Ayuwanna by Barberyn has been my trusted go-to place whenever I''m in Colombo. It''s a proper Ayurveda clinic, built on traditional principles, clear protocols, and guided by highly experienced senior doctors.');
INSERT INTO reviews (center_id, review_text) VALUES (12, 'Ayuwanna by Barberyn is one of best Ayurveda treatment in Colombo since i have tried many different places. Each visit begins with a consultation with the graceful Dr. Sewwandi, who carefully tailors every treatment to your needs.');
INSERT INTO reviews (center_id, review_text) VALUES (12, 'Ayuwanna by Barberyn is a quiet gem in the heart of Colombo. From the moment you arrive, the space feels calm and deeply relaxing.');
INSERT INTO reviews (center_id, review_text) VALUES (12, 'It''s such a lovely place with peace, well hidden in the city center of Colombo. The doctor has been practicing for decades and explained the philosophy of Ayurveda to us.');
INSERT INTO reviews (center_id, review_text) VALUES (13, 'If you are searching for a trustworthy caregiver in Colombo, this is an excellent choice. His reliability, kindness, and commitment to quality care make a real difference.');
INSERT INTO reviews (center_id, review_text) VALUES (13, 'I got treatment from Ayurvani, as the first experience of unani medication. I''m really satisfied with it because my problem was totally cured. The doctor also was friendly and explained the condition very well.');
INSERT INTO reviews (center_id, review_text) VALUES (13, 'I had a very positive experience at this clinic. Unlike the Western medicine I used before, the results here have been truly satisfactory. The doctor is responsive and friendly.');
INSERT INTO reviews (center_id, review_text) VALUES (13, 'Had a consultation and follow up with Dr Nizam and she was absolutely wonderful. She reviewed my medical history in depth with me then recommended a specialized treatment plan.');
INSERT INTO reviews (center_id, review_text) VALUES (14, 'Visited this person for a leg sprain. The only thing she did was talk nothing much. She didn''t even care to take a close look for my leg and only provided me with two bottles of her own brand oil.');
INSERT INTO reviews (center_id, review_text) VALUES (14, 'I went there after phoning her if they have a massage therapy service for my back. The lady gives a fluke answer and in distress I managed to get there. No massage at all. Then she decides on her own and gives me oil to scrub.');
INSERT INTO reviews (center_id, review_text) VALUES (14, 'Dr Mangalambigai changed my life completely and helped me transform to a completely ayurvedic chemical free life. Their medicines are really effective even though it takes a little time for healing.');
INSERT INTO reviews (center_id, review_text) VALUES (14, 'Highly recommend the doctor to all your problems. Ayurvedic doctor is the best person to take care of your health.');
INSERT INTO reviews (center_id, review_text) VALUES (15, 'I had an incredible experience at this Ayurveda center. From the very beginning, I felt I was in expert hands. The doctor spent over an hour conducting a very detailed examination.');
INSERT INTO reviews (center_id, review_text) VALUES (15, 'I completed a full 7-day program with Doctor including all the procedures which he kindly adapted to suit my possibilities. He was also very accommodating with scheduling.');
INSERT INTO reviews (center_id, review_text) VALUES (15, 'I did a 10-day Panchakarma treatment here and I''m so glad I did. The experience felt authentic, well-guided, and deeply supportive from start to finish.');
INSERT INTO reviews (center_id, review_text) VALUES (15, 'I had a full body massage at the center. I am very satisfied with the approach of the entire staff, including the doctor, who knows exactly what he is doing. The prices are great.');
INSERT INTO reviews (center_id, review_text) VALUES (16, 'I had a wonderful experience at AYURDI Ayurveda Medical Center & Pharmacy in Hikkaduwa. I completed a 3-day detox program, finishing with a glow facial on the final day, and I couldn''t be happier.');
INSERT INTO reviews (center_id, review_text) VALUES (16, 'Great ayurvedic clinic! Dr. Shanika is very experienced with all kinds of treatments and takes lots of time for her patients. Everything from dosha consultation to massages was handled with great profession and fair pricing.');
INSERT INTO reviews (center_id, review_text) VALUES (16, 'I had a two-week panchakarma programme at the Ayurdi Ayurveda Retreat Medical Centre in Hikkaduwa. I was impressed by the professionalism and good care of Dr Sandya and Dr Shanika.');
INSERT INTO reviews (center_id, review_text) VALUES (16, 'Dr. Shanika is absolutely wonderful. She is very solution focused and looks to address the root cause. My broken sleep was fixed within two nights.');
INSERT INTO reviews (center_id, review_text) VALUES (17, 'My grandmother had a damage in her backbone and was suffering from pain and mobility issues. Within just one week, she showed great improvement and was able to walk without support.');
INSERT INTO reviews (center_id, review_text) VALUES (17, 'I am incredibly grateful to Dr. Jagath Kahandugoda for the care and treatment I received for my disc bulge back pain. From the very first consultation, I felt listened to, supported, and reassured.');
INSERT INTO reviews (center_id, review_text) VALUES (17, 'I was suffering from severe sciatica and a herniated disc. Two neurosurgeons told me surgery was the only option. I found Dr. Jagath and decided to try Ayurvedic treatment instead. Within two months, the pain was almost completely gone.');
INSERT INTO reviews (center_id, review_text) VALUES (17, 'I would like to express my heartfelt gratitude to Ayurvedic Dr. Jagath Kahadugoda, a specialist in fractures and dislocations. After just a single visit, I was completely relieved of my back pain.');
INSERT INTO reviews (center_id, review_text) VALUES (18, 'Excellent Ayurvedic Care. I was feeling very unwell and had severe body discomfort, barely able to walk. I received a 3-hour oil massage followed by a session in the steamer. The clinic is clean, the staff are very skilled.');
INSERT INTO reviews (center_id, review_text) VALUES (18, 'Myself and 2 friends, visiting from the US, thoroughly enjoyed our treatments. MYND was very accommodating booking us. The spaces were very clean and the entire staff were very nice.');
INSERT INTO reviews (center_id, review_text) VALUES (18, 'I went here for a wart removal. The place was nice and welcoming. Most importantly the place was very clean. The doctor and her staff was very polite and attentive.');
INSERT INTO reviews (center_id, review_text) VALUES (18, 'I had a very good experience with the Ayurvedic therapy here. The treatment was professional, and the atmosphere was welcoming and well-managed.');
INSERT INTO reviews (center_id, review_text) VALUES (19, 'Heritance Ayurvedara Beruwala is simply extraordinary. It is not a normal hotel, but an authentic Ayurveda experience and total regeneration. Treatments are the real strength: competent doctors, personalized therapies daily.');
INSERT INTO reviews (center_id, review_text) VALUES (19, 'I recently attended an Ayurvedic Yoga Retreat. During my visit I had a consultation with the Ayurvedic Nutritionist Manikya Ranashinghe. I thought she was VERY knowledgeable.');
INSERT INTO reviews (center_id, review_text) VALUES (19, 'The best combination of perfect medical ayurvedic treatment and marvellous hotel/food. 14 days and 5kg less with very little effort. Most efficient and joyful treatment.');
INSERT INTO reviews (center_id, review_text) VALUES (19, 'I would like to sincerely thank you for the beautiful moments I experienced during my 16-day stay with you. I enjoyed so many wonderful experiences – from my daily treatments to yoga sessions and meditation.');
INSERT INTO reviews (center_id, review_text) VALUES (20, 'We visited AIDA Ayurveda Resort yesterday and had a really pleasant experience. The staff was incredibly friendly and welcoming throughout our stay. Dr. Chandani for the Ayurvedic consultations and treatments.');
INSERT INTO reviews (center_id, review_text) VALUES (20, 'We had a wonderful experience at Aida Ayurvedic Resort. The main reason was the staff. They were all courteous friendly enthusiastic & helpful. The therapists were also very skilled at their crafts.');
INSERT INTO reviews (center_id, review_text) VALUES (20, 'Highly recommend Aida Ayurveda Resort & Spa, best massage & healing treatment I have ever experienced. Came here with pain issues & they fixed the issue very quickly.');
INSERT INTO reviews (center_id, review_text) VALUES (20, 'I had a wonderful experience at the ayurveda resort. Specially the warm hospitality and the treatment for all the main concerns I had. Dr Radha did an amazing job.');
INSERT INTO reviews (center_id, review_text) VALUES (21, 'It was a wonderful time at the Fewas Ayurveda Resort. Every single member of the team is so warm and welcoming. Fewas has the best doctor – with decades of experience in pulse diagnosis.');
INSERT INTO reviews (center_id, review_text) VALUES (21, 'Fewas Ayurveda Resort — a place that takes healing seriously, without taking itself too seriously. I spent 4 weeks at Fewas and it was honestly a great experience: high-quality treatments, a calm atmosphere.');
INSERT INTO reviews (center_id, review_text) VALUES (21, 'A truly exceptional Ayurveda resort! The doctor is highly competent, supported by an outstanding team of skilled therapists. The healthy food is delicious. The accommodations are spotless.');
INSERT INTO reviews (center_id, review_text) VALUES (21, 'Great resort to visit for meditation and relaxation. Very peaceful and calm, healthy food options, great hospitality, gorgeous beach adjoining the hotel as well!');
INSERT INTO reviews (center_id, review_text) VALUES (22, 'I had such a wonderful and deeply fulfilling experience at Jeevaka Ayurveda Retreat. From the very beginning, I felt completely at ease and genuinely cared for. The program itself was thoughtfully designed.');
INSERT INTO reviews (center_id, review_text) VALUES (22, 'My stay at Jeevaka Villa & Ayurveda Retreat was truly a peaceful and rejuvenating experience. The Ayurveda treatments were excellent—very professional and authentic.');
INSERT INTO reviews (center_id, review_text) VALUES (22, 'The stay here was truly wonderful. From the very beginning, the hospitality of the family that runs this place made me feel incredibly welcome. I loved every treatment, but the yoga in the mornings was definitely my highlight.');
INSERT INTO reviews (center_id, review_text) VALUES (22, 'My experience at Jeevaka Villa & Ayurveda Retreat was absolutely exceptional. From the serene surroundings to the professional Ayurveda treatments, everything felt thoughtfully designed.');
INSERT INTO reviews (center_id, review_text) VALUES (23, 'Amazing staff, great smily and friendly receptionist, professional practitioner, plus great body oil massage! Highly recommend, will come back.');
INSERT INTO reviews (center_id, review_text) VALUES (23, 'Calm soothing massage performed by Dilan who was very professional and thorough. Good massage technique and intensity. Very clean room and have parking for few cars.');
INSERT INTO reviews (center_id, review_text) VALUES (23, 'Aksaaya is a great wellness center. I went for a head and foot massage here, the massages were exceptional. Staff is really friendly as well.');
INSERT INTO reviews (center_id, review_text) VALUES (23, 'If u want to de relax come quick Join wth aksaaya. good medicin and thritments ur body');
INSERT INTO reviews (center_id, review_text) VALUES (24, 'I had a wonderful experience at Siddhalepa Spa. The atmosphere is calm and inviting, and the products used are excellent. A doctor first evaluates you and then recommends suitable treatments.');
INSERT INTO reviews (center_id, review_text) VALUES (24, 'Went to get a therapy done on my hand, which has been stiff/sore, and ended up having both forearms massaged and fermented, and had a gorgeous head massage too. Madhushika was friendly and incredibly skilled.');
INSERT INTO reviews (center_id, review_text) VALUES (24, 'I visited Siddhalepa Ayurveda Clinic (Colombo 7) and it was honestly one of the best wellness experiences I''ve ever had. After a quick and professional consultation with the doctor, the treatment started.');
INSERT INTO reviews (center_id, review_text) VALUES (24, 'I recently visited Siddhalepa Spa and had a truly relaxing and rejuvenating experience. From the moment I walked in, the atmosphere was calm, welcoming, and deeply rooted in traditional Ayurvedic wellness.');
INSERT INTO reviews (center_id, review_text) VALUES (25, 'Had a wonderful spa experience today. The massage was very relaxing and professional. The therapist gave excellent service and made me feel completely comfortable.');
INSERT INTO reviews (center_id, review_text) VALUES (25, 'I booked this place based on high ratings, but the reality was extremely disappointing. The consultant spent time explaining the treatment, yet I was not even sure if she was a qualified Ayurveda doctor. The facility is inside a shopping mall, with no washroom.');
INSERT INTO reviews (center_id, review_text) VALUES (25, 'Deepika was amazing! So professional and great therapist, highly recommend her! The place was extremely clean and smelled amazing.');
INSERT INTO reviews (center_id, review_text) VALUES (25, 'I had a really great experience at this spa. The place is clean, relaxing, and very well maintained, which immediately made me feel comfortable.');
INSERT INTO reviews (center_id, review_text) VALUES (26, 'I had a full-body massage from Shanika, and it was incredibly relaxing. She did an excellent job and made the whole experience very comfortable. The doctor was also very nice, friendly, and professional.');
INSERT INTO reviews (center_id, review_text) VALUES (26, 'I had a wonderful experience here. The service was very professional and the staff were very kind and welcoming. My massage therapist Danushi did an amazing job.');
INSERT INTO reviews (center_id, review_text) VALUES (26, '7-Star Review for Ceylon Hospital Wellness. I had an exceptional experience. From the moment we arrived, we were warmly welcomed by the staff and made to feel comfortable and valued.');
INSERT INTO reviews (center_id, review_text) VALUES (26, 'I had a wonderful full-body oil treatment at CH Wellness. This was my third visit, and once again I had a very relaxing and rejuvenating experience.');
INSERT INTO reviews (center_id, review_text) VALUES (27, 'Santani was one of the most peaceful weeks I have ever experienced. From the moment I arrived, the entire team made me feel incredibly well looked after. My daily treatments were the highlights of my days.');
INSERT INTO reviews (center_id, review_text) VALUES (27, 'Santani was truly one of the most peaceful and unforgettable wellness experiences I have ever had. The property is absolutely stunning, surrounded by breathtaking nature and incredible views.');
INSERT INTO reviews (center_id, review_text) VALUES (27, 'My recent four-night stay at Santani Wellness Kandy was one of the most restorative and memorable hotel experiences I have had anywhere in the world.');
INSERT INTO reviews (center_id, review_text) VALUES (27, 'Our stay at Santani Wellness Kandy was truly unforgettable. The hotel itself is absolutely stunning: peaceful atmosphere, breathtaking mountain views.');
INSERT INTO reviews (center_id, review_text) VALUES (28, 'Stunning location, nestled in amongst dense jungle trees with a flowing river & vibrant wildlife. Each hut is private & has individual showers. The staff are highly skilled, very friendly & helpful.');
INSERT INTO reviews (center_id, review_text) VALUES (28, 'Nirwaan Ayurveda was an experience like no other. The staff were very kind and welcoming and made me feel at home. It is 100% worth your money because I fell asleep midway through the experience.');
INSERT INTO reviews (center_id, review_text) VALUES (28, 'I had an Ayurvedic treatment at Nirwan Ayurvedic Center, and it was a wonderful experience. The treatment was very relaxing and professional, and the hospitality was excellent.');
INSERT INTO reviews (center_id, review_text) VALUES (28, 'Nirvana Ayurveda Spa is a great place to enjoy a relaxing massage. The atmosphere is peaceful, the staff are friendly and professional, and the treatment was very soothing.');
INSERT INTO reviews (center_id, review_text) VALUES (29, 'This massage parlour was recommended by my driver, and it turned out to be such a wonderful experience. Michael and Michelle did our massages, and they were both very respectful, attentive, and kind.');
INSERT INTO reviews (center_id, review_text) VALUES (29, 'There''s no way this place is getting anything less than 5 stars from me! The atmosphere is relaxing from the moment you walk in! Then you''re greeted with a homemade cool drink.');
INSERT INTO reviews (center_id, review_text) VALUES (29, 'We visited LAAMA Grand Wellness Kandy after it was recommended. We booked the Ayurveda Voyage Package. Unfortunately, our experience was completely different from the good reviews we read.');
INSERT INTO reviews (center_id, review_text) VALUES (29, 'Had an incredible experience at Laama Grand Wellness Kandy! My therapist, Ven, was excellent! she was professional, skilled, and constantly made sure I was comfortable.');
INSERT INTO reviews (center_id, review_text) VALUES (30, 'Absolutely incredible place with an amazing, friendly atmosphere full of tranquillity and positive energy. The architecture and design of this place are immaculate.');
INSERT INTO reviews (center_id, review_text) VALUES (30, 'We looked for a place to explore the south of Sri Lanka and it was fantastic! We were here with our 2 grown up children. The rooms are big and well designed, very tranquil.');
INSERT INTO reviews (center_id, review_text) VALUES (30, 'Really loved staying at Roots Retreat. It''s a peaceful nature getaway tucked away in a quiet green setting, but still close enough to town.');
INSERT INTO reviews (center_id, review_text) VALUES (30, 'Roots Retreat is a truly special place where you immediately feel at home. From the very first moment, there is a sense of calm, mindfulness, and authenticity.');
INSERT INTO reviews (center_id, review_text) VALUES (31, 'If you think the previous reviews are all too good to be true (like I did when I booked Sama) - prepare to be proven wrong! My week at Sama was remarkable. The most incredible hospitality, food, treatments and activities.');
INSERT INTO reviews (center_id, review_text) VALUES (31, 'By some good fortune I found SAMA retreats online and decided to book for a 9 day Ayurvedic wellness package. It exceeded every expectation I had. My daily massages were extraordinary.');
INSERT INTO reviews (center_id, review_text) VALUES (31, 'Sama is a truly magical place. The owner had a vision to create a haven in nature and he succeeded in every way. The result is utterly serene and peaceful.');
INSERT INTO reviews (center_id, review_text) VALUES (31, 'I recently spent 3 days and 2 nights at this resort, and it was exactly the peaceful escape I needed. The service was impeccable, with staff who were genuinely attentive and warm.');
INSERT INTO reviews (center_id, review_text) VALUES (32, 'I had the most incredible 60-minute Abhyanga massage with Nadeesha at Spa Secret in Negombo. From the moment I arrived, the experience was exceptional. I left feeling completely refreshed and renewed.');
INSERT INTO reviews (center_id, review_text) VALUES (32, 'I had a wonderful experience at Spa Secret. The foot massage and head massage were both excellent. The therapists were professional, skilled, and made me feel completely relaxed.');
INSERT INTO reviews (center_id, review_text) VALUES (32, 'Today I received an exceptionally skilful massage by Meena, probably one of the best I ever had. She truly cared for my wellbeing and helped me to relax.');
INSERT INTO reviews (center_id, review_text) VALUES (32, 'I went for a massage there today and I''m absolutely thrilled! I felt comfortable as soon as I arrived – everything was very clean, modern, and tastefully decorated.');
INSERT INTO reviews (center_id, review_text) VALUES (33, 'My Wife and I had the full body massage. Gayani was my masseuse who had great pressure and great flow throughout, very relaxing and professional. Very welcoming and a reasonable price.');
INSERT INTO reviews (center_id, review_text) VALUES (33, 'My wife and I went here for a 90 minute full body massage. We chose this place because of the good reviews and the good price. The massage did not disappoint.');
INSERT INTO reviews (center_id, review_text) VALUES (33, 'Competitively priced and well done full body massage. On a down side they did not provide slippers to take a shower in. Easy to locate and plenty of parking. Very hospitable staff.');
INSERT INTO reviews (center_id, review_text) VALUES (33, 'Such a nice place! Everyone who works there knows exactly what they''re doing. We were welcomed warm and friendly. Really customer friendly prices!');
INSERT INTO reviews (center_id, review_text) VALUES (34, 'I had a terrible experience at Ayur Bliss today. The spa is nothing like what they advertise. The staff were not professional, and the overall hygiene was very poor. The treatment rooms were tiny.');
INSERT INTO reviews (center_id, review_text) VALUES (34, 'I was in Sri Lanka 2 weeks ago, this place just next to my accommodation and walked down to get a massage. The Dr recommend natural steam massage is the best.');
INSERT INTO reviews (center_id, review_text) VALUES (34, 'I''ve had many massages but this one wasn''t the best one. First of all I asked for a medium pressure massage. First of all the massage was very light pressure. I was very confused when I was told it''s over.');
INSERT INTO reviews (center_id, review_text) VALUES (34, 'One of the best experiences I had in Sri Lanka! I had a full-body massage, and it was incredibly relaxing. Ivon was wonderful, very kind and attentive.');
INSERT INTO reviews (center_id, review_text) VALUES (35, 'I had a wonderful treatment experience at Arved Ashram. I had been suffering from back pain and sciatica for a long time. After the treatment, I felt amazing and experienced significant relief.');
INSERT INTO reviews (center_id, review_text) VALUES (35, 'Today I found this newly opened business in a quiet area of Negombo beach. I tried the special offer this morning which was an hour head and foot massage - it was excellent.');
INSERT INTO reviews (center_id, review_text) VALUES (35, 'A wonderful wellness experience! The staff were friendly, professional, and attentive. The treatments were relaxing, and the environment was clean and peaceful.');
INSERT INTO reviews (center_id, review_text) VALUES (35, 'Highly recommend');
INSERT INTO reviews (center_id, review_text) VALUES (36, 'Jasmine Village is a wonderful place to stay, and the deluxe rooms are truly outstanding. We first came here by chance for an afternoon massage and were pleasantly surprised by the high quality.');
INSERT INTO reviews (center_id, review_text) VALUES (36, 'I had an amazing experience with an authentic Sri Lankan herbal massage here. The location is beautiful, clean, and very well maintained. The therapists are highly experienced and professional.');
INSERT INTO reviews (center_id, review_text) VALUES (36, 'I had a 75-minute massage for 6,600 rupees, which also included hotel pickup and drop-off – excellent value. The male therapists were outstanding.');
INSERT INTO reviews (center_id, review_text) VALUES (36, 'The overall experience at this hotel was mixed. The information provided on the website did not match the actual services offered. Cleanliness was below expectations, especially in the rooms.');
INSERT INTO reviews (center_id, review_text) VALUES (37, 'The doctor is very attentive and, judging by the constant lineup of patients, highly qualified. I ordered several shirodhara and massages of various body parts; the massage was a bit harsh for me, but the oil was good.');
INSERT INTO reviews (center_id, review_text) VALUES (37, 'I do not recommend this place, especially not for young female travellers. I was given a male masseuse who made me feel very uncomfortable. He regularly left me exposed and in very vulnerable positions.');
INSERT INTO reviews (center_id, review_text) VALUES (37, 'Unforgettable Personalized Care! I came for the full body massage and steam bath. Dr. Saranga was incredibly helpful, knowledgeable, and provided personal care throughout my visit.');
INSERT INTO reviews (center_id, review_text) VALUES (37, 'The people were really nice but the massage and the room not so good. The rooms and hygiene were not the best. They didn''t change the towel with previous client.');
INSERT INTO reviews (center_id, review_text) VALUES (38, 'We stayed at this hotel in Negombo and honestly had an excellent experience from beginning to end. The staff were incredibly friendly and helpful at all times.');
INSERT INTO reviews (center_id, review_text) VALUES (38, 'Set in unspoilt natural surroundings, the hotel is beautifully appointed, offers professional massage therapists in its own spa area, and also provides a taxi service and boat trips.');
INSERT INTO reviews (center_id, review_text) VALUES (38, 'My stay at ayur ayur has been exceptional from the first moment I arrived! All the staff are beautiful, friendly and welcoming. The authentic ayurvedic treatments are the best!');
INSERT INTO reviews (center_id, review_text) VALUES (38, '5 stars for Kavindra, he made our stay exceptionally smooth. we went out and beyond to serve our needs always with a smile.');
INSERT INTO reviews (center_id, review_text) VALUES (39, 'Absolutely amazing treatment! I had the Laawanya Full Body Glowing Ritual and loved every minute of it. I was even more impressed to learn that my therapist was visually impaired.');
INSERT INTO reviews (center_id, review_text) VALUES (39, 'I had an exceptional experience at the hotel''s in-house wellness center. The service is warm, attentive, and very professional. The meditation sessions are truly relaxing.');
INSERT INTO reviews (center_id, review_text) VALUES (39, 'I had a facial and shirodhara here and they were both 5 stars. The staff are wonderful, you have a free consult with a doctor before your treatment.');
INSERT INTO reviews (center_id, review_text) VALUES (39, 'My husband and I both had massages today at LA Ceylon Wellness and the staff were fabulous. It was a truly wonderful experience. One of the best massages we''ve ever had.');
INSERT INTO reviews (center_id, review_text) VALUES (40, 'Not sure why generally in sri lanka did not have like nice relax spa centre, instead all look alike this in the picture. I think the skill can be better, reasonable price for one hour.');
INSERT INTO reviews (center_id, review_text) VALUES (40, 'After reading so many great reviews on Google Maps, I decided to try a massage here as well. My friend recommended the Shirodhara treatment. It was gentle, relaxing, and completely pain-free.');
INSERT INTO reviews (center_id, review_text) VALUES (40, 'Amazing!!! I had a one hour whole body massage and it was excellent. I live in Thailand and get massages almost every week. This was definitely one of the best I have had.');
INSERT INTO reviews (center_id, review_text) VALUES (40, 'I had a 60 minute total body massage that elevated my senses not only through the massage itself but also through the aromatic oils and creams which they used.');
INSERT INTO reviews (center_id, review_text) VALUES (41, 'I had a wonderful 60-minute foot massage with Kumari. It was incredibly relaxing and exactly what I needed. Her technique was perfect, and I felt completely refreshed afterwards.');
INSERT INTO reviews (center_id, review_text) VALUES (41, 'I highly recommend this place. I had a full-body massage and a Shirodhara treatment, and both were excellent. Chami was my therapist, and he did a fantastic job.');
INSERT INTO reviews (center_id, review_text) VALUES (41, 'We have made a couple massage and both of our therapist are awesome! They even offer us a herbal tea which is fantastic.');
INSERT INTO reviews (center_id, review_text) VALUES (41, 'One of the best relaxation experiences in Sri Lanka. We booked a couple''s session and it was perfect. The therapists are highly skilled and professional.');
INSERT INTO reviews (center_id, review_text) VALUES (42, 'I had a lovely massage and steam therapy. The environment was beautiful and soothing and I came out totally relaxed. I slept so well.');
INSERT INTO reviews (center_id, review_text) VALUES (42, 'SEENBEST Ella');
INSERT INTO reviews (center_id, review_text) VALUES (42, 'Just perfect, all of it. Really recommend');
INSERT INTO reviews (center_id, review_text) VALUES (42, 'I had an incredibly relaxing Ayurvedic full-body massage with Dr. Kaushalya, and it was such a wonderful experience. I felt so calm, relaxed, and refreshed afterwards.');
INSERT INTO reviews (center_id, review_text) VALUES (43, 'The place is run by a group of lovely and skilled ladies. I had a full body Ayurvedic Massage and Shirodhura treatment, overall it lasted almost two hours and the whole experience was really relaxing.');
INSERT INTO reviews (center_id, review_text) VALUES (43, 'Nice Full Body ayurvedic massage, rooms were not so cozy, but I enjoyed the Massage for 70min for a reasonable Price. We enjoyed tea and fruits after the massage.');
INSERT INTO reviews (center_id, review_text) VALUES (43, 'Amazing experience! I''m such a picky person when it comes to massage, but the masseurs are great! We had the Ayurvedic full body massage 70 mins and they offered tea.');
INSERT INTO reviews (center_id, review_text) VALUES (43, 'We got a 70-minute Ayurvedic full-body massage here. My masseuse was Chandra, and her pressure was absolutely perfect. I felt incredibly relaxed and completely at ease.');
INSERT INTO reviews (center_id, review_text) VALUES (44, 'Unlike typical spas, this place offers therapy tailored to you. Dr. Nipun Hasantha begins with a pulse diagnosis, then uses homemade herbal oils, stone therapy, and personalized treatments.');
INSERT INTO reviews (center_id, review_text) VALUES (44, 'Fantastic experience. I sincerely recommend this place. Nipun is the best! It''s not a common massage like the ones you can get anywhere across Sri Lanka. It''s tailormade.');
INSERT INTO reviews (center_id, review_text) VALUES (44, 'I had a massage yesterday with Nipun, and it was honestly a unique experience unlike anything I''ve ever tried before. Within just a few seconds of observing my body, he was able to identify the two main issues.');
INSERT INTO reviews (center_id, review_text) VALUES (44, 'The Sri Lankan ayurvedic treatment of Nipun and his sister was exactly what I needed, because I had shoulder pain and it totally disappeared with only 1-2 sessions.');
INSERT INTO reviews (center_id, review_text) VALUES (45, 'We had an absolutely wonderful experience at this spa in Sri Lanka. We enjoyed a 30-minute foot massage, and honestly, it was so relaxing and enjoyable that we wished it would never end.');
INSERT INTO reviews (center_id, review_text) VALUES (45, 'Wow, what an experience. I had a full body 1hour massage by Latha and it made me feel so amazing, I left feeling so rejuvenated! My partner had her massage done by Nisha.');
INSERT INTO reviews (center_id, review_text) VALUES (45, 'One of the best massages I''ve ever had. It was the perfect way to relax after our 10km hike to Ella rock. This spa is slightly hidden up the hill from town but absolutely worth finding!');
INSERT INTO reviews (center_id, review_text) VALUES (45, 'We had a great experience here during our stay in Ella. The atmosphere was calm and welcoming, the treatment was very relaxing, and the staff were kind and professional.');
INSERT INTO reviews (center_id, review_text) VALUES (46, 'Wish I had found the place sooner! I went there 2 times, had a leg and foot massage and a full body massage. It was wonderful! Everything was very professional.');
INSERT INTO reviews (center_id, review_text) VALUES (46, 'One of the best massages ever! I had 90 minutes deep tissue massage and the pressure was just enough for my muscular body to feel it deeply, but still balanced.');
INSERT INTO reviews (center_id, review_text) VALUES (46, 'Excellent service, aromatic scents, strong massage, hot tea at the end. And the most beautiful dog Lulu');
INSERT INTO reviews (center_id, review_text) VALUES (46, 'My bf and I went for a relaxing full body massage and foot massage. The massage itself was good although they cut it 15min short. Also the setup of this shop is a bit strange.');
INSERT INTO reviews (center_id, review_text) VALUES (47, 'I booked cupping therapy, Deep tissue massage, and Head massage with Tharushi, and it was amazing. She helped relieve my muscle tension and stress. The spa is clean and peaceful.');
INSERT INTO reviews (center_id, review_text) VALUES (47, 'Highly recommended! I had a massage with Wathsala and it was absolutely excellent. Very professional, skilled, and attentive throughout the entire session.');
INSERT INTO reviews (center_id, review_text) VALUES (47, 'The reviews for this place are good and I intended to come here during my 5 nights in Tangalle. It''s actually fresh aloe too and it was fantastic.');
INSERT INTO reviews (center_id, review_text) VALUES (47, 'I had a fantastic Aloe Vera full body massage with Shanika. She was very professional, attentive, and really knew how to relieve tension.');
INSERT INTO reviews (center_id, review_text) VALUES (48, 'I had an amazing experience at Talking Fingers Spa in Tangalle. From the moment I walked in, the atmosphere was calm, welcoming, and perfect for relaxation.');
INSERT INTO reviews (center_id, review_text) VALUES (48, 'We had such a great experience here! The massage was truly excellent – very relaxing and done with great care and professionalism. We left feeling refreshed and completely relaxed.');
INSERT INTO reviews (center_id, review_text) VALUES (48, 'We celebrated our 20 years anniversary with a pampering experience at Talking fingers spa in Tangalle. We had a lovely time and we were treated like royalty.');
INSERT INTO reviews (center_id, review_text) VALUES (48, 'I had two massages back-to-back: one full-body massage with fresh aloe and the other a facial massage with herbs. It was an exceptional experience.');
INSERT INTO reviews (center_id, review_text) VALUES (49, 'I visited Dhamma Kuta for a Vipassana course in November 2025. It was a truly wonderful experience. The entire staff was incredibly kind, the natural surroundings were beautiful, and the atmosphere was peaceful.');
INSERT INTO reviews (center_id, review_text) VALUES (49, 'If you are planning to do vipassana for first time then Dhamma kuta is great place to start this journey of mind purity. Just take the plunge and sign up for 10 days beginner course.');
INSERT INTO reviews (center_id, review_text) VALUES (49, 'I completed my first Vipassana retreat here and had a wonderful experience. The centre is so beautiful with wonderful nature and people and a very supportive atmosphere.');
INSERT INTO reviews (center_id, review_text) VALUES (49, 'Best place for receiving right meditation technique and deep philosophy about lifestyle.');
INSERT INTO reviews (center_id, review_text) VALUES (50, 'Very calm and peaceful place located at Colombo. They have meditation and religious programs. We can take sponsorship of these programs. But not enough parking facilities.');
INSERT INTO reviews (center_id, review_text) VALUES (50, 'One of the best meditation center located in heart of Colombo, Srilanka. Great place to learn about the Buddhist meditation according to the Supreme Buddha.');
INSERT INTO reviews (center_id, review_text) VALUES (50, 'In a neighborhood that seems to have an abundance of Buddhist religious establishments, this meditation center''s grounds are attractive and partially open to the public.');
INSERT INTO reviews (center_id, review_text) VALUES (50, 'I came to visit this international centre. There is not one sign in English. The signs are all in Sinhalese. The reception seemed empty. Zero information and zero welcome for foreigners.');
INSERT INTO reviews (center_id, review_text) VALUES (51, 'IMPORTANT: It''s too noisy for meditation. I wouldn''t recommend this place because it is very close to the main road. You can hear traffic noise, music from the road, and sounds.');
INSERT INTO reviews (center_id, review_text) VALUES (51, 'Stillness Amidst Noise. Dhamma Sobha sits on a wooded hillside, about 47 kilometers from Colombo – the closest Vipassana center to the city.');
INSERT INTO reviews (center_id, review_text) VALUES (51, 'Vipassana is a really interesting technique. For me the whole experience was way too religious. Everyone has to decide for themselves if Vipassana is a good thing for them.');
INSERT INTO reviews (center_id, review_text) VALUES (51, 'I followed the 10-day Vipassana course here about a year ago. A few days before arriving, I read quite a lot of reviews mentioning the noise. I still decided to go and don''t regret coming here!');
INSERT INTO reviews (center_id, review_text) VALUES (53, 'This meditation center is truly a place of peace and healing. The American monk teaches with great kindness, patience, and deep understanding of the mind.');
INSERT INTO reviews (center_id, review_text) VALUES (53, 'I had the opportunity to visit this place three times for meditation, and each experience was truly meaningful. It was very interesting to learn more about Buddhist philosophy.');
INSERT INTO reviews (center_id, review_text) VALUES (53, 'I am so grateful to have found out about this venue and had the opportunity to attend the guided meditation and dhamma talk with Bhante. Highly recommended!');
INSERT INTO reviews (center_id, review_text) VALUES (53, 'If you''re looking for peace or a moment of stillness, I recommend Weligama Vipassana Meditation. It''s a place filled with calm, but also with Buddhist wisdom.');
INSERT INTO reviews (center_id, review_text) VALUES (54, 'Just finished a 10 day retreat there. Best center I''ve been yet. Only single rooms. Nice walking area.');
INSERT INTO reviews (center_id, review_text) VALUES (54, 'Tranquil Oasis for Deep Meditation. Nestled next to two serene lakes, this center offers a perfect blend of natural beauty and peaceful atmosphere.');
INSERT INTO reviews (center_id, review_text) VALUES (54, 'A great place to practice Vipassana meditation, there are 10 days course, 20 days, 30 days, 45 days course.');
INSERT INTO reviews (center_id, review_text) VALUES (54, 'How to find words for this experience? Life-changing that''s for sure! I finally released the fear of death and tension that I lived with in my body for 45 years.');
INSERT INTO reviews (center_id, review_text) VALUES (55, 'I spent some of the most beautiful days of my life here. If you''re genuinely interested in Vipassana meditation, this is truly the place to be.');
INSERT INTO reviews (center_id, review_text) VALUES (55, 'I spent a beautiful week in this place. I just found it by chance in Google and sent an email asking to join a Vipassana retreat. I just loved it, it was a peaceful week.');
INSERT INTO reviews (center_id, review_text) VALUES (55, 'calm place to do meditation, Buddhist temple in Pugoda road');
INSERT INTO reviews (center_id, review_text) VALUES (55, 'A Truly Authentic Vipassana Experience (Mahasi Tradition). Kanduboda Siyane is one of the oldest and most respected Vipassana meditation centres in Sri Lanka.');
INSERT INTO reviews (center_id, review_text) VALUES (56, 'Did my second 10 day sitting course there and after 10 day service. The center is really simple yet really welcoming environment surrounded by jungle and sounds of animals.');
INSERT INTO reviews (center_id, review_text) VALUES (56, 'This is so peaceful and calm place of Dhamma. We had everyday delicious Sri Lankan rice and curry and fruit juices. Rooms are small but you have everything you need.');
INSERT INTO reviews (center_id, review_text) VALUES (56, 'It''s full of animals this place. In the rooms you have mosquitoes, frogs, spiders and other small insects. But I had a very good experience because the place is beautiful.');
INSERT INTO reviews (center_id, review_text) VALUES (56, 'Vipassana Center Review. It was my first Vipassana course, and the experience was truly transformative. By the end of the course, I felt a deep sense of calm and clarity.');
INSERT INTO reviews (center_id, review_text) VALUES (57, 'Very beautiful location with healing environment. Good for meditation and relaxing with natural resources. Buddhist monks are very kind and helpful.');
INSERT INTO reviews (center_id, review_text) VALUES (57, 'Forest monastery under the tradition of kalyani yogashrama, one would need to take a 2km walk from the parking point to the main hall.');
INSERT INTO reviews (center_id, review_text) VALUES (57, 'So quiet forest temple in hedigalla srilanka, it''s close to sinharaja forest.');
INSERT INTO reviews (center_id, review_text) VALUES (57, 'Take a moment to relax at a Buddhist temple situated in the serene surroundings of a wetland forest.');
INSERT INTO reviews (center_id, review_text) VALUES (58, 'I had the misfortune of arriving in Jaffna with severe back pain – the kind that makes even sitting, sleeping, or simply enjoying your surroundings impossible. Under the care of Dr. Thedsanamurthy Sabesan, I experienced one of the most effective treatments I have ever received.');
INSERT INTO reviews (center_id, review_text) VALUES (58, 'Many thanks for having accept my request: in very good health, asking for a ayurveda body massage. It''s the best massage I received in Sri Lanka. You have a high level of expertise.');
INSERT INTO reviews (center_id, review_text) VALUES (58, 'I recently had a wonderful Ayurvedic massage at Sri Ayush Ayurvedic Clinic. The massage was performed by two skilled doctors, and I felt very comfortable and well taken care of.');
INSERT INTO reviews (center_id, review_text) VALUES (58, 'I''ve had many Ayurvedic massages over the years while living in India, but this one in Jaffna was by far the best. I felt incredible relief from muscular pain.');
INSERT INTO reviews (center_id, review_text) VALUES (63, 'I had severe spasms in my belly and Dr. Shani consulted me, after about a month, I have a really good improvement and I still continue the treatments. Highly recommended');
INSERT INTO reviews (center_id, review_text) VALUES (63, 'open everyday. free. Friendly service. No polythene, plastic zone.');
INSERT INTO reviews (center_id, review_text) VALUES (63, 'The very best place to get ayurvedic treatment.');
INSERT INTO reviews (center_id, review_text) VALUES (63, 'No people like old medical system');
INSERT INTO reviews (center_id, review_text) VALUES (66, 'I had a great experience at Santhusha Ayurveda Medical Centre for my back pain. It''s a wonderful family-owned practice where Dr. Lahiru and Dr. Hasini provide incredible patient care.');
INSERT INTO reviews (center_id, review_text) VALUES (66, 'I had been suffering from severe back pain for about a year. However, after learning about this doctor and visiting him, he took an X-ray and completely cured my back pain within about a week.');
INSERT INTO reviews (center_id, review_text) VALUES (66, 'I had severe leg pain and received treatment at Santhusha Ayurveda Medical Center, and I am extremely happy with the results. Now my leg pain is completely cured.');
INSERT INTO reviews (center_id, review_text) VALUES (66, 'Life-Changing Ayurvedic Treatment. I visited Santhusha Ayurveda suffering from severe back pain and stiffness throughout my entire body and joints. The transformation has been absolutely incredible!');
INSERT INTO reviews (center_id, review_text) VALUES (68, 'This family is a good Ayurveda medical team. The daughter is a doctor and make the consultation. The father make the medicine. And the mother make good massage.');
INSERT INTO reviews (center_id, review_text) VALUES (68, 'One of best places to do Ayurvedic massage in Galle. They use homemade medicines. That''s what makes this place more special.');
INSERT INTO reviews (center_id, review_text) VALUES (68, 'I appreciate your hospitality!! I''m glad I could experience the real Ayurvedic massage at a reasonable price. They''re very welcomed and warm.');
INSERT INTO reviews (center_id, review_text) VALUES (68, 'I experienced a full body massage by Dr. Unais and I can highly recommend it to anyone! I felt very nice and relieved afterwards, he is a kind, open and very lovely person.');
INSERT INTO reviews (center_id, review_text) VALUES (69, 'We had a wonderful experience at this Ayurvedic clinic. We spent 5 days with our friends. Doctor Shalika and Amali and the whole staff is attentive, kind, and truly caring.');
INSERT INTO reviews (center_id, review_text) VALUES (69, 'I spent three weeks doing my Ayurveda cure at Procare Ayush Ayurvedic Home and can absolutely recommend it. The care provided by the medical team was excellent, highly competent, attentive.');
INSERT INTO reviews (center_id, review_text) VALUES (69, 'I had a wonderful experience at Procare Ayush Ayurvedic Home! We booked a couple''s Ayurvedic full body massage, and it was fantastic. Dr. Shalika was a great host.');
INSERT INTO reviews (center_id, review_text) VALUES (69, 'We were recommended Procare by Suresh, the manager at Three Gables. It was excellent - very clean - the consultation was informative, the treatments very relaxing.');
INSERT INTO reviews (center_id, review_text) VALUES (73, 'We had a wonderful experience at the Dhara Healing Ayurveda Treatment Center in Nuwara Eliya, where we booked as a family an Ayurvedic massage together. The atmosphere felt very welcoming and trustworthy.');
INSERT INTO reviews (center_id, review_text) VALUES (73, 'My visit to Dhara Healing Ayurveda Treatment Center was absolutely amazing! From the moment I entered, I felt calm and welcomed by the soothing music and relaxing scent.');
INSERT INTO reviews (center_id, review_text) VALUES (73, 'The therapist I had was good and professional. Nevertheless the whole experience was unpleasant. First of all the hygiene was questionable. The massage bed was covered only with small paper towel.');
INSERT INTO reviews (center_id, review_text) VALUES (73, 'Very relaxing and aromatic Ayurvedic treatment in Nuwara Eliya. The massage therapist had good pressure and was very professional. This is mid-range and value for money.');
INSERT INTO reviews (center_id, review_text) VALUES (75, 'To start with, our masseuses were excellent. We came for the honeymoon package. However, 2 days ago the spa team were informed that the pool and spa facilities were being refurbished.');
INSERT INTO reviews (center_id, review_text) VALUES (75, 'I had an amazing experience at Grand Thai Spa. From the moment I walked in, the atmosphere was calm, welcoming, and beautifully maintained. The staff were extremely professional and friendly.');
INSERT INTO reviews (center_id, review_text) VALUES (75, 'Great professional experience! Kirna was very friendly and had very strong hands. You can specify what kind of pressure points need to be handled and the service was amazing and clean.');
INSERT INTO reviews (center_id, review_text) VALUES (75, 'I recently had a wonderful spa treatment at The Grand Spa in Nuwara Eliya, and it was truly an amazing experience. A very special thank you to Weda for her exceptional service.');
INSERT INTO reviews (center_id, review_text) VALUES (76, 'We have a lot of experience to compare, and I would love to leave a higher rating because Vihara and Tharu—the ladies who give the massages—are very nice, welcoming, and friendly.');
INSERT INTO reviews (center_id, review_text) VALUES (76, 'Beware of scams! This centre was recommended to us by a local. On arrival, we were told that the full-body massage would cost 15,000 rupees. That seemed quite expensive to us.');
INSERT INTO reviews (center_id, review_text) VALUES (76, 'We had a lovely time with Vihara and Tharu. Very kind ladies and a my boyfriend and I had lovely hour long massage and steam after our Pekoe trail.');
INSERT INTO reviews (center_id, review_text) VALUES (76, 'Rustic authentic massage with steam cupboard was nice to do on a cold day, the massage was with vihara who was very kind and gave a nice massage, good to do after a trek.');
