-- ============================================================
-- Ayurveda & Spiritual Tourism Matching System - Database Schema
-- Generated from live application data. Safe to run on a fresh
-- MySQL database: creates tables, then populates with real data
-- (83 centers, their reviews, and the condition-dosha-treatment
-- mapping used by the matching engine).
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ------------------------------------------------------------
-- Table: centers
-- One row per Ayurveda/wellness/spiritual center.
-- ------------------------------------------------------------
DROP TABLE IF EXISTS centers;
CREATE TABLE centers (
    center_id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    category ENUM('Curative', 'Wellness/Rejuvenative', 'Spiritual/Meditation') NOT NULL,
    conditions_text TEXT,
    dosha_focus VARCHAR(50),
    price_tier VARCHAR(50),
    phone VARCHAR(50),
    latitude DECIMAL(9,6),
    longitude DECIMAL(9,6),
    district VARCHAR(100),
    address VARCHAR(500),
    verified_status VARCHAR(255),
    notes TEXT,
    google_rating DECIMAL(2,1),
    google_review_count INT,
    nlp_quality_score DECIMAL(3,2),
    nlp_quality_source VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ------------------------------------------------------------
-- Table: reviews
-- Individual review snippets per center (used by the NLP
-- sentiment/aspect pipeline and the safety risk-flag detector).
-- ------------------------------------------------------------
DROP TABLE IF EXISTS reviews;
CREATE TABLE reviews (
    review_id INT AUTO_INCREMENT PRIMARY KEY,
    center_id INT NOT NULL,
    review_text TEXT NOT NULL,
    is_risk_flagged BOOLEAN DEFAULT FALSE,
    FOREIGN KEY (center_id) REFERENCES centers(center_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ------------------------------------------------------------
-- Table: condition_dosha_mapping
-- Condition -> dosha -> expected duration -> outcome likelihood.
-- Source: domain-expert (Ayurvedic physician) interview,
-- triangulated with published literature and market cross-checks.
-- ------------------------------------------------------------
DROP TABLE IF EXISTS condition_dosha_mapping;
CREATE TABLE condition_dosha_mapping (
    condition_id INT AUTO_INCREMENT PRIMARY KEY,
    condition_name VARCHAR(255) NOT NULL UNIQUE,
    duration_range VARCHAR(100),
    duration_source VARCHAR(500),
    outcome_likelihood_pct INT,
    outcome_source VARCHAR(500)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ------------------------------------------------------------
-- Table: matching_sessions
-- One row per tourist search/match session. 'tourist_id' is an
-- EXTERNAL reference to the itinerary team's base tourist_profiles
-- table (name, nationality, travel dates) - confirm exact column
-- name/type with them before enabling the foreign key constraint.
-- This table only stores health/matching-specific data - it does
-- NOT duplicate the base tourist profile.
-- ------------------------------------------------------------
DROP TABLE IF EXISTS matching_sessions;
CREATE TABLE matching_sessions (
    session_id INT AUTO_INCREMENT PRIMARY KEY,
    tourist_id INT NOT NULL COMMENT 'External FK - itinerary team base tourist_profiles table',
    path ENUM('ayurveda', 'spiritual') NOT NULL,
    condition_name VARCHAR(255),
    companion_condition_name VARCHAR(255) NULL,
    predicted_dosha VARCHAR(20),
    dosha_confidence_pct DECIMAL(5,1),
    budget_tier VARCHAR(50),
    matched_center_id INT,
    match_pct INT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (matched_center_id) REFERENCES centers(center_id) ON DELETE SET NULL
    -- FOREIGN KEY (tourist_id) REFERENCES itinerary_team_db.tourist_profiles(tourist_id)
    --   ^ uncomment and adjust once the itinerary team confirms their schema
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS = 1;

